# ARC Prize 2026 ARC-AGI-2: one-cell offline submission runner
# Copy this entire file into one Kaggle Notebook code cell and run it.
# It writes /kaggle/working/submission.json.

from __future__ import annotations

import base64
import gzip
import hashlib
import io
import json
import os
import signal
import shutil
import sys
import tarfile
import time
import zipfile
from pathlib import Path


SOLVER_REVISION = "bundle-sha256:293ce0e6176ab23c861cbb90c9b74fa778d19a80879d155df7dd804e3651e5a2"
BUNDLE_SHA256 = "293ce0e6176ab23c861cbb90c9b74fa778d19a80879d155df7dd804e3651e5a2"
TEST_MEMBER = "arc-agi_test_challenges.json"
SAMPLE_MEMBER = "sample_submission.json"
RUN_ROOT = Path(os.environ.get("ARC2_WORK_ROOT", "/kaggle/working"))
OUTPUT_PATH = RUN_ROOT / "submission.json"
EMBEDDED_ROOT = RUN_ROOT / "arc2_embedded_solver"
EMBEDDED_MARKER = EMBEDDED_ROOT / ".solver_revision"

_BUNDLE_B64 = """

"""


class _TaskTimeoutError(Exception):
    pass


def _competition_rerun() -> bool:
    value = os.environ.get("KAGGLE_IS_COMPETITION_RERUN")
    return value is not None and value.strip().lower() not in {"", "0", "false", "no"}


def _task_timeout_seconds() -> float:
    try:
        return max(0.0, float(os.environ.get("ARC2_TASK_TIMEOUT_SECONDS", "60")))
    except (TypeError, ValueError):
        return 60.0


def _safe_extract_bundle() -> None:
    compressed = base64.b64decode(_BUNDLE_B64)
    if hashlib.sha256(compressed).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError("embedded solver bundle digest mismatch")
    bundle_identity = f"{SOLVER_REVISION}:{BUNDLE_SHA256}"
    if (
        EMBEDDED_MARKER.exists()
        and EMBEDDED_MARKER.read_text(encoding="ascii") == bundle_identity
    ):
        return
    if EMBEDDED_ROOT.exists():
        shutil.rmtree(EMBEDDED_ROOT)
    EMBEDDED_ROOT.mkdir(parents=True)
    payload = gzip.decompress(compressed)
    package_root = EMBEDDED_ROOT / "arc_agi_2_solver"
    package_root.mkdir(parents=True, exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(payload), mode="r:") as archive:
        for member in archive.getmembers():
            name = Path(member.name)
            if member.isdir():
                continue
            if member.issym() or member.islnk() or name.is_absolute() or ".." in name.parts:
                raise RuntimeError(f"unsafe embedded solver member: {member.name}")
            if name.parts[:1] != ("arc_agi_2_solver",) or not member.isfile():
                raise RuntimeError(f"unexpected embedded solver member: {member.name}")
            target = EMBEDDED_ROOT / name
            target.parent.mkdir(parents=True, exist_ok=True)
            source = archive.extractfile(member)
            if source is None:
                raise RuntimeError(f"cannot read embedded solver member: {member.name}")
            target.write_bytes(source.read())
    (EMBEDDED_ROOT / "arc_agi_2_solver" / "__init__.py").touch()
    EMBEDDED_MARKER.write_text(bundle_identity, encoding="ascii")


def _read_json_file(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def _load_from_zip(path: Path):
    with zipfile.ZipFile(path) as archive:
        names = set(archive.namelist())
        missing = [member for member in (TEST_MEMBER, SAMPLE_MEMBER) if member not in names]
        if missing:
            raise FileNotFoundError(f"{path} is missing {missing}")
        return (
            json.loads(archive.read(TEST_MEMBER)),
            json.loads(archive.read(SAMPLE_MEMBER)),
            str(path),
        )


def _load_competition_data():
    # ARC Prize Kaggle inputs are normally individual JSON files. The ZIP path
    # is also accepted for local reproduction of the same cell.
    configured = os.environ.get("ARC2_DATA_PATH")
    roots = []
    if configured:
        roots.append(Path(configured))
    attached_root = Path("/kaggle/input/arc-prize-2026-arc-agi-2")
    rerun_root = Path("/kaggle/input/competitions/arc-prize-2026-arc-agi-2")
    roots.extend(
        [rerun_root, attached_root, Path("/kaggle/input")]
        if _competition_rerun()
        else [attached_root, rerun_root, Path("/kaggle/input")]
    )
    seen: set[Path] = set()
    for root in roots:
        if not root.exists():
            continue
        if root.is_file() and root.suffix.lower() == ".zip":
            return _load_from_zip(root)
        if root.is_file() and root.name == TEST_MEMBER:
            sample = root.with_name(SAMPLE_MEMBER)
            if sample.exists():
                return _read_json_file(root), _read_json_file(sample), str(root.parent)
        if not root.is_dir():
            continue
        direct_test = root / TEST_MEMBER
        direct_sample = root / SAMPLE_MEMBER
        if direct_test.exists() and direct_sample.exists():
            return _read_json_file(direct_test), _read_json_file(direct_sample), str(root)
        for candidate in sorted(root.rglob(TEST_MEMBER)):
            if candidate in seen:
                continue
            seen.add(candidate)
            sample = candidate.with_name(SAMPLE_MEMBER)
            if sample.exists():
                return _read_json_file(candidate), _read_json_file(sample), str(candidate.parent)
        for candidate in sorted(root.rglob("*.zip")):
            if candidate in seen:
                continue
            seen.add(candidate)
            try:
                return _load_from_zip(candidate)
            except (FileNotFoundError, KeyError, zipfile.BadZipFile):
                continue
    raise FileNotFoundError(
        "ARC2 input not found. Attach the official competition data or set "
        "ARC2_DATA_PATH to its directory or ZIP for local reproduction."
    )


def _valid_grid(grid) -> bool:
    if not isinstance(grid, list) or not grid or not isinstance(grid[0], list) or not grid[0]:
        return False
    if len(grid) > 30 or len(grid[0]) > 30:
        return False
    width = len(grid[0])
    return all(
        isinstance(row, list)
        and len(row) == width
        and all(isinstance(value, int) and 0 <= value <= 9 for value in row)
        for row in grid
    )


def _safe_grid(grid):
    if not isinstance(grid, list) or not grid:
        return [[0]]
    rows = grid[:30]
    width = min(
        30,
        max(
            (len(row) if isinstance(row, list) else 0)
            for row in rows
        ),
    )
    if width <= 0:
        return [[0]]
    fixed = []
    for row in rows:
        source = row if isinstance(row, list) else []
        fixed_row = []
        for value in source[:width]:
            try:
                normalized = int(value)
            except (TypeError, ValueError):
                normalized = 0
            fixed_row.append(max(0, min(9, normalized)))
        fixed_row.extend([0] * (width - len(fixed_row)))
        fixed.append(fixed_row)
    return fixed or [[0]]


def _fallback_grid(task, test_index: int):
    if not isinstance(task, dict):
        return [[0]]
    test_items = task.get("test")
    if not isinstance(test_items, list) or test_index >= len(test_items):
        return [[0]]
    test_item = test_items[test_index]
    if not isinstance(test_item, dict):
        return [[0]]
    return _safe_grid(test_item.get("input"))


def _solve_with_timeout(solve_task, task):
    timeout_seconds = _task_timeout_seconds()
    if (
        timeout_seconds <= 0
        or not hasattr(signal, "SIGALRM")
        or not hasattr(signal, "setitimer")
    ):
        return solve_task(task)

    def _raise_timeout(_signum, _frame):
        raise _TaskTimeoutError(
            f"task exceeded {timeout_seconds:g} second runtime boundary"
        )

    previous_handler = signal.getsignal(signal.SIGALRM)
    signal.signal(signal.SIGALRM, _raise_timeout)
    signal.setitimer(signal.ITIMER_REAL, timeout_seconds)
    try:
        return solve_task(task)
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous_handler)


def _validate_submission(submission, sample_submission) -> None:
    if sorted(submission) != sorted(sample_submission):
        raise ValueError(
            f"task ID mismatch: produced={len(submission)} sample={len(sample_submission)}"
        )
    for task_id, sample_entries in sample_submission.items():
        entries = submission.get(task_id)
        if not isinstance(entries, list) or len(entries) != len(sample_entries):
            raise ValueError(f"test entry count mismatch for task {task_id}")
        for entry in entries:
            if set(entry) != {"attempt_1", "attempt_2"}:
                raise ValueError(f"attempt keys mismatch for task {task_id}")
            if not _valid_grid(entry["attempt_1"]) or not _valid_grid(entry["attempt_2"]):
                raise ValueError(f"invalid ARC grid for task {task_id}")


def _run(solve_task_override=None) -> dict:
    started = time.perf_counter()
    if solve_task_override is None:
        _safe_extract_bundle()
        if str(EMBEDDED_ROOT) not in sys.path:
            sys.path.insert(0, str(EMBEDDED_ROOT))
        from arc_agi_2_solver.solver_core import solve_task
    else:
        solve_task = solve_task_override

    test_challenges, sample_submission, input_source = _load_competition_data()
    if not isinstance(test_challenges, dict) or not isinstance(sample_submission, dict):
        raise TypeError("competition challenge and sample payloads must be mappings")
    submission = {}
    real_attempts = 0
    placeholder_attempts = 0
    duplicate_non_placeholder = 0
    invalid_grid_fallbacks = 0
    prediction_count_adjustments = 0
    missing_test_tasks = 0
    task_error_types = {}
    task_timeout_count = 0
    for task_id, sample_entries in sample_submission.items():
        if not isinstance(sample_entries, list):
            raise TypeError("sample submission task entries must be lists")
        task = test_challenges.get(task_id)
        result = None
        if not isinstance(task, dict):
            missing_test_tasks += 1
        else:
            try:
                result = _solve_with_timeout(solve_task, task)
            except Exception as exc:
                error_name = type(exc).__name__
                task_error_types[error_name] = task_error_types.get(error_name, 0) + 1
                if isinstance(exc, _TaskTimeoutError):
                    task_timeout_count += 1

        predictions = getattr(result, "predictions", [])
        if not isinstance(predictions, list):
            predictions = []
        prediction_count_adjustments += abs(len(predictions) - len(sample_entries))
        entries = []
        for test_index in range(len(sample_entries)):
            fallback = _fallback_grid(task, test_index)
            prediction = predictions[test_index] if test_index < len(predictions) else None
            attempts = getattr(prediction, "attempts", [])
            if not isinstance(attempts, list):
                attempts = []
            entry = {}
            prior_real_outputs = []
            for attempt_index, attempt_key in enumerate(("attempt_1", "attempt_2")):
                attempt = attempts[attempt_index] if attempt_index < len(attempts) else None
                output = getattr(attempt, "output", None)
                source = getattr(attempt, "source", "submission_boundary_fallback")
                if not _valid_grid(output):
                    output = fallback
                    source = "submission_boundary_fallback"
                    invalid_grid_fallbacks += 1
                entry[attempt_key] = output
                if source == "placeholder_input" or source == "submission_boundary_fallback":
                    placeholder_attempts += 1
                    continue
                real_attempts += 1
                if output in prior_real_outputs:
                    duplicate_non_placeholder += 1
                prior_real_outputs.append(output)
            entries.append(entry)
        submission[task_id] = entries

    _validate_submission(submission, sample_submission)
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT_PATH.write_text(
        json.dumps(submission, separators=(",", ":"), ensure_ascii=False),
        encoding="utf-8",
    )
    report = {
        "solver_revision": SOLVER_REVISION,
        "bundle_sha256": BUNDLE_SHA256,
        "input_source": input_source,
        "test_task_count": len(test_challenges),
        "sample_task_count": len(sample_submission),
        "submission_entry_count": sum(len(entries) for entries in submission.values()),
        "submission_path": str(OUTPUT_PATH),
        "submission_shape_compatible": True,
        "real_attempt_count": real_attempts,
        "placeholder_attempt_count": placeholder_attempts,
        "duplicate_non_placeholder_grid_count": duplicate_non_placeholder,
        "competition_rerun": _competition_rerun(),
        "task_timeout_seconds": _task_timeout_seconds(),
        "task_error_count": sum(task_error_types.values()),
        "task_error_types": dict(sorted(task_error_types.items())),
        "task_timeout_count": task_timeout_count,
        "missing_test_task_count": missing_test_tasks,
        "extra_test_task_count": len(set(test_challenges) - set(sample_submission)),
        "prediction_count_adjustment_count": prediction_count_adjustments,
        "invalid_grid_fallback_count": invalid_grid_fallbacks,
        "solution_members_loaded": [],
        "internet_or_external_api": False,
        "runtime_seconds": round(time.perf_counter() - started, 6),
    }
    (OUTPUT_PATH.parent / "arc2_kaggle_run_report.json").write_text(
        json.dumps(report, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    print(json.dumps(report, ensure_ascii=False, sort_keys=True))
    print(f"READY: {OUTPUT_PATH}")
    return report


if __name__ == "__main__":
    _run()
